import React from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import Layout from './components/Layout';
import Home from './pages/Home';
import Strategies from './pages/Strategies';
import ToolsDatabase from './pages/ToolsDatabase';
import Hardware from './pages/Hardware';
import Blockers from './pages/Blockers';
import AssistiveTech from './pages/AssistiveTech';

const App: React.FC = () => {
  return (
    <Router>
      <Layout>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/strategies" element={<Strategies />} />
          <Route path="/tools" element={<ToolsDatabase />} />
          <Route path="/hardware" element={<Hardware />} />
          <Route path="/blockers" element={<Blockers />} />
          <Route path="/assistive-tech" element={<AssistiveTech />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, BookOpen, PenTool, ShieldAlert, Home, Database, Cpu } from 'lucide-react';

interface LayoutProps {
  children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const location = useLocation();

  const navItems = [
    { name: 'Home', path: '/', icon: <Home className="w-4 h-4 mr-2" /> },
    { name: 'Strategies', path: '/strategies', icon: <BookOpen className="w-4 h-4 mr-2" /> },
    { name: 'Blockers', path: '/blockers', icon: <ShieldAlert className="w-4 h-4 mr-2" /> },
    { name: 'Assistive Tech', path: '/assistive-tech', icon: <Cpu className="w-4 h-4 mr-2" /> },
    { name: 'Tools DB', path: '/tools', icon: <Database className="w-4 h-4 mr-2" /> },
    { name: 'Hardware', path: '/hardware', icon: <PenTool className="w-4 h-4 mr-2" /> },
  ];

  const isActive = (path: string) => location.pathname === path;

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      {/* Navigation */}
      <nav className="sticky top-0 z-50 bg-white border-b border-slate-200 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex">
              <div className="flex-shrink-0 flex items-center">
                <Link to="/" className="flex items-center gap-2">
                  <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold text-xl">
                    A
                  </div>
                  <span className="font-bold text-slate-800 text-lg hidden sm:block">Academic Productivity</span>
                </Link>
              </div>
              <div className="hidden md:ml-6 md:flex md:space-x-4 items-center">
                {navItems.map((item) => (
                  <Link
                    key={item.name}
                    to={item.path}
                    className={`inline-flex items-center px-3 py-2 rounded-md text-sm font-medium transition-colors duration-150 ${
                      isActive(item.path)
                        ? 'bg-blue-50 text-blue-700'
                        : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
                    }`}
                  >
                    {item.icon}
                    {item.name}
                  </Link>
                ))}
              </div>
            </div>
            <div className="-mr-2 flex items-center md:hidden">
              <button
                onClick={() => setIsMenuOpen(!isMenuOpen)}
                className="inline-flex items-center justify-center p-2 rounded-md text-slate-400 hover:text-slate-500 hover:bg-slate-100 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500"
              >
                <span className="sr-only">Open main menu</span>
                {isMenuOpen ? <X className="block h-6 w-6" /> : <Menu className="block h-6 w-6" />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile menu */}
        {isMenuOpen && (
          <div className="md:hidden bg-white border-b border-slate-200">
            <div className="pt-2 pb-3 space-y-1 px-2">
              {navItems.map((item) => (
                <Link
                  key={item.name}
                  to={item.path}
                  onClick={() => setIsMenuOpen(false)}
                  className={`flex items-center px-3 py-4 rounded-md text-base font-medium ${
                    isActive(item.path)
                      ? 'bg-blue-50 text-blue-700'
                      : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
                  }`}
                >
                  {item.icon}
                  {item.name}
                </Link>
              ))}
            </div>
          </div>
        )}
      </nav>

      {/* Main Content */}
      <main className="flex-grow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {children}
        </div>
      </main>

      {/* Footer */}
      <footer className="bg-slate-900 text-slate-300">
        <div className="max-w-7xl mx-auto py-12 px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div>
              <h3 className="text-white text-lg font-semibold mb-4">About</h3>
              <p className="text-sm leading-relaxed">
                Based on resources developed by Dominik Lukeš for the Reading and Writing Innovation Lab. 
                Dedicated to helping students and academics improve their digital workflows.
              </p>
            </div>
            <div>
              <h3 className="text-white text-lg font-semibold mb-4">Key Sections</h3>
              <ul className="space-y-2 text-sm">
                <li><Link to="/strategies" className="hover:text-white transition-colors">Productivity Strategies</Link></li>
                <li><Link to="/blockers" className="hover:text-white transition-colors">Blockers to Productivity</Link></li>
                <li><Link to="/assistive-tech" className="hover:text-white transition-colors">Assistive Technology</Link></li>
              </ul>
            </div>
            <div>
              <h3 className="text-white text-lg font-semibold mb-4">License</h3>
              <p className="text-sm">
                Licensed under Creative Commons Attribution 4.0 International License.
              </p>
            </div>
          </div>
          <div className="mt-8 border-t border-slate-800 pt-8 text-center text-sm">
            <p>&copy; {new Date().getFullYear()} Academic Productivity Hub. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default Layout;

import React from 'react';
import { Strategy } from '../types';
import { Headphones, ZoomIn, ListTree, Mic } from 'lucide-react';

interface StrategyCardProps {
  strategy: Strategy;
}

const StrategyCard: React.FC<StrategyCardProps> = ({ strategy }) => {
  const getIcon = (name: string) => {
    switch (name) {
      case 'Headphones': return <Headphones className="w-8 h-8 text-blue-600" />;
      case 'ZoomIn': return <ZoomIn className="w-8 h-8 text-purple-600" />;
      case 'ListTree': return <ListTree className="w-8 h-8 text-teal-600" />;
      case 'Mic': return <Mic className="w-8 h-8 text-rose-600" />;
      default: return <Headphones className="w-8 h-8" />;
    }
  };

  const getColorClass = (name: string) => {
    switch (name) {
      case 'Headphones': return 'border-l-4 border-blue-500';
      case 'ZoomIn': return 'border-l-4 border-purple-500';
      case 'ListTree': return 'border-l-4 border-teal-500';
      case 'Mic': return 'border-l-4 border-rose-500';
      default: return 'border-l-4 border-gray-500';
    }
  };

  return (
    <div className={`bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 p-6 ${getColorClass(strategy.iconName)}`}>
      <div className="flex items-center gap-4 mb-4">
        <div className="p-3 bg-slate-50 rounded-full">
          {getIcon(strategy.iconName)}
        </div>
        <h3 className="text-xl font-bold text-slate-800">{strategy.title}</h3>
      </div>

      <p className="text-slate-600 mb-6 leading-relaxed">
        {strategy.fullDescription}
      </p>

      <div className="bg-slate-50 rounded-md p-4">
        <h4 className="text-sm font-semibold text-slate-900 uppercase tracking-wider mb-3">Actionable Steps</h4>
        <ul className="space-y-2">
          {strategy.actionItems.map((item, idx) => (
            <li key={idx} className="flex items-start text-sm text-slate-700">
              <span className="mr-2 text-blue-500 font-bold">•</span>
              {item}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default StrategyCard;

import React, { useState } from 'react';
import { Tool } from '../types';
import { Check, X, Tag, Globe, Loader2, ExternalLink, ChevronDown, ChevronUp } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface ToolCardProps {
  tool: Tool;
}

const ToolCard: React.FC<ToolCardProps> = ({ tool }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [searchData, setSearchData] = useState<{ text: string; sources: { title: string; uri: string }[] } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async () => {
    if (isExpanded && searchData) {
      setIsExpanded(false);
      return;
    }

    setIsExpanded(true);

    if (searchData) return; // Already fetched

    setIsLoading(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: `Research the current status, pricing, reviews, and key features for "${tool.name}" (${tool.category}). Provide a concise summary helpful for academic productivity decisions.`,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const text = response.text || "No specific information found.";

      // Extract grounding metadata
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = chunks
        .map((chunk: any) => chunk.web)
        .filter((web: any) => web)
        .map((web: any) => ({ title: web.title, uri: web.uri }));

      setSearchData({ text, sources });
    } catch (err) {
      console.error("Search error:", err);
      setError("Failed to load current information. Please check your connection or API key.");
    } finally {
      setIsLoading(false);
    }
  };

  const renderFormattedText = (text: string) => {
    return text.split('\n').map((line, idx) => {
      const trimmed = line.trim();
      if (!trimmed) return <div key={idx} className="h-2" />;

      // Simple bold formatting for **text**
      const parts = line.split(/(\*\*.*?\*\*)/g);
      const content = parts.map((part, i) => {
        if (part.startsWith('**') && part.endsWith('**')) {
          return <strong key={i} className="font-semibold">{part.slice(2, -2)}</strong>;
        }
        return part;
      });

      if (trimmed.startsWith('* ') || trimmed.startsWith('- ')) {
        return (
          <div key={idx} className="flex items-start ml-2 mb-1">
            <span className="mr-2 text-slate-400">•</span>
            <span className="text-slate-700 text-sm">{content}</span>
          </div>
        );
      }

      return <p key={idx} className="text-slate-700 text-sm mb-2">{content}</p>;
    });
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-all duration-200 flex flex-col h-full">
      <div className="p-6 flex-grow">
        <div className="flex justify-between items-start mb-2">
          <span className="inline-block px-2 py-1 text-xs font-semibold tracking-wide text-blue-800 uppercase bg-blue-100 rounded-full">
            {tool.category}
          </span>
          <span className="text-sm font-medium text-slate-500">
            {tool.cost}
          </span>
        </div>

        <h3 className="text-xl font-bold text-slate-900 mb-2">{tool.name}</h3>
        <p className="text-slate-600 text-sm mb-4">{tool.description}</p>

        <div className="grid grid-cols-1 gap-4 mt-4">
          <div>
            <h4 className="text-xs font-semibold text-green-700 uppercase mb-2 flex items-center">
               Pros
            </h4>
            <ul className="space-y-1">
              {tool.pros.slice(0, 3).map((pro, idx) => (
                <li key={idx} className="text-xs text-slate-600 flex items-start">
                  <Check className="w-3 h-3 text-green-500 mr-1 mt-0.5 flex-shrink-0" />
                  {pro}
                </li>
              ))}
            </ul>
          </div>
          <div>
            <h4 className="text-xs font-semibold text-red-700 uppercase mb-2 flex items-center">
               Cons
            </h4>
            <ul className="space-y-1">
              {tool.cons.slice(0, 3).map((con, idx) => (
                <li key={idx} className="text-xs text-slate-600 flex items-start">
                  <X className="w-3 h-3 text-red-500 mr-1 mt-0.5 flex-shrink-0" />
                  {con}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>

      {/* Search Section */}
      <div className={`border-t border-slate-100 bg-slate-50 transition-all duration-300 ${isExpanded ? 'bg-blue-50/50' : ''}`}>
        <button 
          onClick={handleSearch}
          className="w-full px-6 py-3 flex items-center justify-between text-sm font-medium text-blue-600 hover:text-blue-700 hover:bg-blue-50 transition-colors"
        >
          <span className="flex items-center gap-2">
            <Globe className="w-4 h-4" />
            {isExpanded ? 'Hide current info' : 'Search for current info'}
          </span>
          {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
        </button>

        {isExpanded && (
          <div className="px-6 pb-6 pt-2 border-t border-blue-100/50">
            {isLoading ? (
              <div className="flex items-center justify-center py-8 text-blue-600">
                <Loader2 className="w-6 h-6 animate-spin mr-2" />
                <span className="text-sm">Searching live data...</span>
              </div>
            ) : error ? (
              <div className="text-red-500 text-sm py-2">{error}</div>
            ) : searchData ? (
              <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
                <div className="bg-white rounded-lg p-4 border border-blue-100 shadow-sm">
                   {renderFormattedText(searchData.text)}
                </div>

                {searchData.sources.length > 0 && (
                  <div>
                    <h5 className="text-xs font-semibold text-slate-500 uppercase mb-2">Sources</h5>
                    <div className="grid grid-cols-1 gap-2">
                      {searchData.sources.map((source, idx) => (
                        <a 
                          key={idx}
                          href={source.uri}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center text-xs text-blue-600 hover:underline truncate"
                        >
                          <ExternalLink className="w-3 h-3 mr-1 flex-shrink-0" />
                          <span className="truncate">{source.title || source.uri}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
                <div className="text-[10px] text-slate-400 text-right">
                  Generated by Gemini 2.5 Flash
                </div>
              </div>
            ) : null}
          </div>
        )}
      </div>

      <div className="bg-white px-6 py-3 border-t border-slate-100">
        <div className="flex flex-wrap gap-2">
          {tool.relatedStrategies.map((strat) => (
            <span key={strat} className="inline-flex items-center text-xs text-slate-500">
              <Tag className="w-3 h-3 mr-1" />
              {strat}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ToolCard;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

